    ["[表情147]"] = "[Эмодзи 147]",
    ["{{player.name}}对{{targetPlayer.name}}成功进行了安魂，对方躁动的灵性重归宁静，恢复了<Chat_Highlight>{{eventMessageParams.N}}</>点理智。赞美女神，一切的归宿是安宁！"] = "{{player.name}} has successfully performed a Requiem on {{targetPlayer.name}}. The other party's restless Духовность has returned to tranquility, restoring <Chat_Highlight>{{eventMessageParams.N}}</> points of Рассудок. Praise the Goddess, for the destination of all things is peace!",
